// SkillsManager 启动时扫描四层目录（loader.rs:243）
// 优先级：Repo > User > System > Admin

// 发现的 SKILL.md 文件：
// [Repo]   ./.agents/skills/auth-helper/SKILL.md
// [Repo]   ./.agents/skills/ci-runner/SKILL.md
// [User]   ~/.agents/skills/imagegen/SKILL.md
// [User]   ~/.agents/skills/openai-docs/SKILL.md
// [System] $CODEX_HOME/skills/.system/skill-creator/SKILL.md
// [System] $CODEX_HOME/skills/.system/skill-installer/SKILL.md
// [System] $CODEX_HOME/skills/.system/plugin-creator/SKILL.md

// 合并：同名 skill 高优先级覆盖低优先级
// SkillLoadOutcome { skills: Vec<SkillMetadata>, disabled_paths }

{
  "tool": "image_gen",
  "arguments": {
    "prompt": "a cat floating in outer space, surrounded by stars",
    "model": "dall-e-3",
    "size": "1024x1024"
  }
}

// ci-runner skill 被 mention：$ci-runner
// agents/openai.yaml 声明 MCP 依赖
//
// mcp_skill_dependencies.rs 自动安装流程：
// 1. collect_missing_mcp_dependencies()
//    → github MCP server: 未找到
// 2. 弹窗："ci-runner 需要 GitHub MCP server，是否安装？"
//    → 用户选择 Install
// 3. 写入 MCP 配置 → OAuth 认证
//    → McpConnectionManager 重载
//    → github tools 可用
//
// Feature::SkillMcpDependencyInstall（默认开启）
// key: "skill_mcp_dependency_install"
